500		public static <T> void multiRootTreeDfsVisit(List<T> roots, Function<T, List<T>> childrenProvider, Consumer<T> visitor) {
501			Deque<T> queue = new ArrayDeque<>(roots);
502			while (true) {
503				T current = queue.pollLast();
504				if (current == null) {
505					return;
506				}
507				visitor.accept(current);
508				for (T child : childrenProvider.apply(current)) {
509					queue.addLast(child);
510				}
511			}
512		}
