	private static final String JADX_API_PACKAGE = JadxDecompiler.class.getPackage().getName();
	private static final String STACKTRACE_STOP_CLS_NAME = DepthTraversal.class.getName();

	/**
	 * Single source of truth for the primitive type descriptor correspondence.
	 * The smali-to-java and java-to-smali name conversions are both derived from this table,
	 * so the two directions can't drift out of sync.
	 */
	private static final Map<Character, String> SMALI_PRIMITIVE_TO_JAVA;
	private static final Map<String, String> JAVA_PRIMITIVE_TO_SMALI;

	static {
		Map<Character, String> toJava = new HashMap<>();
		toJava.put('V', "void");
		toJava.put('Z', "boolean");
		toJava.put('C', "char");
		toJava.put('B', "byte");
		toJava.put('S', "short");
		toJava.put('I', "int");
		toJava.put('F', "float");
		toJava.put('J', "long");
		toJava.put('D', "double");
		SMALI_PRIMITIVE_TO_JAVA = Collections.unmodifiableMap(toJava);

		Map<String, String> toSmali = new HashMap<>(toJava.size());
		toJava.forEach((smali, java) -> toSmali.put(java, String.valueOf(smali)));
		JAVA_PRIMITIVE_TO_SMALI = Collections.unmodifiableMap(toSmali);
	}

	private Utils() {
	}

	public static String cleanObjectName(String obj) {
		if (obj.charAt(0) == 'L') {
			int last = obj.length() - 1;
			if (obj.charAt(last) == ';') {
				return obj.substring(1, last).replace('/', '.');
			}
		}
		return obj;
	}

	public static String cutObject(String obj) {
		if (obj.charAt(0) == 'L') {
			return obj.substring(1, obj.length() - 1);
		}
		return obj;
	}

	public static String makeQualifiedObjectName(String obj) {
		return 'L' + obj.replace('.', '/') + ';';
	}

	public static String smaliNameToJavaName(String descString) {
		if (descString.isEmpty()) {
			return descString;
		}

		String javaName;
		switch (descString.charAt(0)) {
			case 'V':
				javaName = "void";
				break;
			case 'Z':
				javaName = "boolean";
				break;
			case 'C':
				javaName = "char";
				break;
			case 'B':
				javaName = "byte";
				break;
			case 'S':
				javaName = "short";
				break;
			case 'I':
				javaName = "int";
				break;
			case 'F':
				javaName = "float";
				break;
			case 'J':
				javaName = "long";
				break;
			case 'D':
				javaName = "double";
				break;
			case 'L':
				javaName = cleanObjectNameWithInnerClass(descString);
				break;
			case '[':
				javaName = String.format("%s[]", smaliNameToJavaName(descString.substring(1, descString.length())));
				break;
			default:
				javaName = descString;
				break;
		}
		return javaName;
	}

	private static String cleanObjectNameWithInnerClass(String obj) {
		// Probably can just update the Utils.cleanObjectName method?
		String result = Utils.cleanObjectName(obj);
		return result.replace('$', '.');
	}

	public static String javaNameToSmaliName(String descString) {
		if (descString.isEmpty()) {
			return descString;
		}

		if (descString.endsWith("[]")) {
			return String.format("[%s", javaNameToSmaliName(descString.substring(0, descString.length() - 2)));
		}

		String javaName;
		switch (descString) {
			case "void":
				javaName = "V";
				break;
			case "boolean":
				javaName = "Z";
				break;
			case "char":
				javaName = "C";
				break;
			case "byte":
				javaName = "B";
				break;
			case "short":
				javaName = "S";
				break;
			case "int":
				javaName = "I";
				break;
			case "float":
				javaName = "F";
				break;
			case "long":
				javaName = "J";
				break;
			case "double":
				javaName = "D";
				break;
			default:
				javaName = Utils.makeQualifiedObjectName(descString);
				break;
		}
		return javaName;
