	public static <T> boolean containsInListByRef(List<T> list, T element) {
		if (isEmpty(list)) {
			return false;
		}
		for (T t : list) {
			if (t == element) {
				return true;
			}
		}
		return false;
	}

	public static <T> int indexInListByRef(List<T> list, T element) {
		if (list == null || list.isEmpty()) {
			return -1;
		}
		int size = list.size();
		for (int i = 0; i < size; i++) {
			T t = list.get(i);
			if (t == element) {
